{
  "query": "query Offers($filter: OfferFilterData!, $page: PaginationInput!) {
  offers(filterData: $filter, pagination: $page) {
    pagination { hasMore nextCursor cursor take }
    offers {
      id
      name
      description
      Merchant { id businessName category status }
      CashbackConfigurations { id name eligibleCustomerTypes }
      ExclusiveOffers { id name eligibleCustomerTypes startDate endDate }
      PaybillOrTills { id number type }
    }
  }
}",
  "variables": {
    "filter": {},
    "page": { "take": 10 }
  }
}

{
  "query": "query Offers($filter: OfferFilterData!, $page: PaginationInput!) {\n  offers(filterData: $filter, pagination: $page) {\n    offers { id name Merchant { businessName } }\n  }\n}",
  "variables": {
    "filter": { "search": "java" },
    "page": { "take": 10 }
  }
}

{
  "query": "query Offers($filter: OfferFilterData!, $page: PaginationInput!) {\n  offers(filterData: $filter, pagination: $page) {\n    offers { id name Merchant { businessName category } }\n  }\n}",
  "variables": {
    "filter": { "category": "Retail" },
    "page": { "take": 10 }
  }
}

{
  "query": "query Offers($filter: OfferFilterData!, $page: PaginationInput!) {\n  offers(filterData: $filter, pagination: $page) {\n    offers { id name CashbackConfigurations { name } }\n  }\n}",
  "variables": {
    "filter": { "percentage": "ZeroToFive" },
    "page": { "take": 10 }
  }
}

{
  "query": "query Offers($filter: OfferFilterData!, $page: PaginationInput!) {\n  offers(filterData: $filter, pagination: $page) {\n    pagination { hasMore nextCursor }\n    offers { id name }\n  }\n}",
  "variables": {
    "filter": {},
    "page": { "take": 1, "cursor": null }
  }
}

{
  "query": "query { offers(filterData: {}, pagination: { take: 10 }) { offers { id name CashbackConfigurations { name eligibleCustomerTypes } ExclusiveOffers { name eligibleCustomerTypes } } } }"
}

